#!/bin/bash
sed -i 's/let parsedResults: AnalysisResult;/let parsedResults: AnalysisResult;\n          const isProMode = localStorage.getItem("isProMode") === "true";\n          if (isProMode \&\& localStats) {\n             console.log("PRO MODE: Bypassing server analysis for speed.");\n             parsedResults = { ...localStats, recommendations: [] };\n             const { FEMALE_LIBRARY, MALE_LIBRARY } = await import("..\/data\/haircutLibrary");\n             const lib = parsedResults.gender === "male" ? MALE_LIBRARY : FEMALE_LIBRARY;\n             parsedResults.recommendations = lib.slice(0, 4).map(h => ({ name: h.name, imageKeyword: h.imageKeyword, description: h.description, matchScore: 90 }));\n          } else {/g' src/hooks/useAnalysis.ts

sed -i 's/parsedResults = await analyzeImageApi(formData, telegramInitData) as AnalysisResult;/parsedResults = await analyzeImageApi(formData, telegramInitData) as AnalysisResult;\n          }/g' src/hooks/useAnalysis.ts
